// Keep the screen on during a ride. Primary: the Screen Wake Lock API. Backup: a tiny silent looping video
// (iPhone keeps the screen awake while a video plays), for when the wake lock is refused or dropped.
const CLIP = 'data:video/mp4;base64,';

export class KeepAwake {
  private lock: WakeLockSentinel | null = null;
  private video: HTMLVideoElement | null = null;
  onChange: () => void = () => {};
  get held() { return !!this.lock || (!!this.video && !this.video.paused); }
  get viaLock() { return !!this.lock; }
  async on() {
    if (document.visibilityState !== 'visible') return;
    if (!this.lock && 'wakeLock' in navigator) {
      try {
        this.lock = await navigator.wakeLock.request('screen');
        this.lock.addEventListener('release', () => { this.lock = null; this.onChange(); });
      } catch { this.lock = null; }
    }
    // The video runs as well: iPhone sometimes drops the wake lock without telling the page.
    if (!this.video) {
      const v = document.createElement('video');
      v.setAttribute('playsinline', ''); v.setAttribute('muted', ''); v.muted = true; v.loop = true; v.src = CLIP;
      v.setAttribute('aria-hidden', 'true');
      v.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;opacity:0.01;pointer-events:none;z-index:-1';
      v.addEventListener('pause', () => this.onChange()); v.addEventListener('playing', () => this.onChange());
      document.body.append(v); this.video = v;
    }
    if (this.video.paused) { try { await this.video.play(); } catch { /* needs a tap first */ } }
    this.onChange();
  }
  async off() {
    try { await this.lock?.release(); } catch { /* already gone */ }
    this.lock = null;
    this.video?.pause();
    this.onChange();
  }
}
